export function generate100Levels() {
  return Array.from({ length: 100 }, (_, i) => {
    const levelNumber = i + 1;
    let cefr = 'A1';
    if (levelNumber > 80) cefr = 'C2';
    else if (levelNumber > 60) cefr = 'C1';
    else if (levelNumber > 45) cefr = 'B2';
    else if (levelNumber > 30) cefr = 'B1';
    else if (levelNumber > 15) cefr = 'A2';

    let status = 'locked';
    let stars = 0;
    let score = 0;

    if (levelNumber === 1) {
      status = 'unlocked';
    }

    return {
      id: levelNumber,
      level_number: levelNumber,
      title: LEVEL_TITLES[i] || `Advanced English Level ${levelNumber}`,
      cefr_band: cefr,
      description: `Master key sentence structures, idioms, and fluent vocabulary tailored for ${cefr} level proficiency.`,
      required_vocab_count: 15 + (levelNumber % 10) * 2,
      required_reading_title: `Reading Exercise ${levelNumber}: ${LEVEL_TITLES[i]}`,
      unlock_score_threshold: 80,
      status,
      stars,
      score,
    };
  });
}

